from tilelang import tvm as tvm
from tvm import tirx
from tvm.target import Target
from tvm.ir.base import Node
from tvm.ir import Range
from tvm.runtime import Scriptable
import tvm_ffi
from .registry import resolve_gemm_impl
from tilelang import _ffi_api


@tvm_ffi.register_global_func("tl.gemm.infer_layout")
def gemm_infer_layout(gemm, target: Target, thread_bounds: Range):
    thread_nums = thread_bounds.extent
    return gemm.infer_layout(target, thread_nums)


@tvm_ffi.register_global_func("tl.gemm.lower")
def gemm_lower(
    gemm,
    layout_map,
    target: Target,
    thread_bounds: Range,
    thread_index: tirx.PrimExpr,
    mbar_phase_expr: tirx.PrimExpr,
):
    # We pass thread_bounds rather than thread_extents because tcgen5mma need to check this
    stmt = gemm.lower(layout_map, target, thread_bounds, thread_index, mbar_phase_expr)
    return stmt


@tvm_ffi.register_object("tl.Gemm")
class Gemm(Node, Scriptable):
    # FFI fields (LLVM/MLIR-style lowerCamel via reflection):
    # a, b, c, aPtr, bPtr, cPtr, m, n, k, transA, transB,
    # strideA, strideB, offsetA, offsetB, clearAccum, kPack, wgWait, policy
    #
    # Backward-compat alias properties are provided below to support old names.

    # Backward-compat alias properties (old API → new FFI fields)
    @property
    def A(self):
        return self.a

    @property
    def B(self):
        return self.b

    @property
    def C(self):
        return self.c

    @property
    def APtr(self):
        return self.aPtr

    @property
    def BPtr(self):
        return self.bPtr

    @property
    def CPtr(self):
        return self.cPtr

    @property
    def M(self):
        return self.m

    @property
    def N(self):
        return self.n

    @property
    def K(self):
        return self.k

    @property
    def trans_A(self):
        return self.transA

    @property
    def trans_B(self):
        return self.transB

    @property
    def stride_A(self):
        return self.strideA

    @property
    def stride_B(self):
        return self.strideB

    @property
    def offset_A(self):
        return self.offsetA

    @property
    def offset_B(self):
        return self.offsetB

    @property
    def clear_accum(self):
        return self.clearAccum

    @property
    def k_pack(self):
        return self.kPack

    @property
    def wg_wait(self):
        return self.wgWait

    @property
    def is_tcgen05(self):
        return getattr(self, "isTcgen05", False)

    @property
    def sf_k_start(self):
        return self.sfKStart

    def infer_layout(self, target: Target, thread_nums: int):
        """Infer the layout for the GEMM operation based on target architecture."""
        gemm_inst = self._select_gemm_instruction(thread_nums, target)
        impl_class = self._get_implementation_class(gemm_inst, target)
        return impl_class(self).infer_layout(target, thread_nums)

    def lower(
        self,
        layout_map: dict,
        target: Target,
        thread_bounds: Range,
        thread_index: tirx.PrimExpr,
        mbar_phase_expr: tirx.PrimExpr,
    ):
        """Lower the GEMM operation to TIR statements based on target architecture."""
        thread_nums = thread_bounds.extent
        gemm_inst = self._select_gemm_instruction(thread_nums, target)
        impl_class = self._get_implementation_class(gemm_inst, target)
        return impl_class(self).lower(layout_map, target, thread_bounds, thread_index, mbar_phase_expr)

    def _select_gemm_instruction(self, thread_nums: int, target: Target) -> str:
        """Select the appropriate GEMM instruction key based on target and thread configuration.

        The selection logic chooses:
        1. TCGEN5MMA for Blackwell architecture
        2. WGMMA for Hopper architecture with sufficient matrix size and warp count
        3. MFMA for CDNA (AMD) architecture
        4. MMA for CUDA architecture
        5. Scalar for CPU target (scalar fallback)

        Args:
            thread_nums: Number of threads in the block
            target: Target architecture

        Returns:
            The selected backend-specific GEMM instruction key.
        """
        return str(_ffi_api.GemmGetGemmInstructionKey(self, int(thread_nums), target))

    def _get_implementation_class(self, gemm_inst: str, target: Target):
        """Get the appropriate implementation class for the given GEMM instruction key.

        Args:
            gemm_inst: The selected backend-specific GEMM instruction key
            target: Target architecture

        Returns:
            The implementation class for the instruction key

        Raises:
            NotImplementedError: If the instruction key is not supported
            ValueError: If the instruction key is unknown
        """
        return resolve_gemm_impl(gemm_inst, target)

from __future__ import annotations

from dataclasses import dataclass
from tilelang import tvm as tvm
from tvm.target import Target
from tvm.ir import Range
from tvm import tirx
from tilelang import language as T
from tilelang.utils.language import is_shared, is_fragment, is_tensor_memory
from tilelang.tileop.base import GemmWarpPolicy
from tilelang.language.dtypes import validate_gemm_ab_dtypes
from tvm.ir.base import Node
from tvm.ir import PrimExpr


@dataclass
class GemmBase:
    """Base class for GEMM tile operators.

    Classifies the GEMM variant by the memory scopes of operands A and B
    (SS, SR, RS, TS, RR) and provides common property accessors for the
    underlying ``gemm_node`` IR node.
    """

    gemm_node: Node

    def __post_init__(self) -> None:
        validate_gemm_ab_dtypes(
            self.A.dtype,
            self.B.dtype,
            a_in_tmem=is_tensor_memory(self.A),
            allow_f8f6f4_mixed=self.allow_f8f6f4_mixed_dtypes,
        )

    @property
    def allow_f8f6f4_mixed_dtypes(self) -> bool:
        # TODO(wt): Consider enabling mixed f8f6f4 operands for MMA paths too.
        return False

    def infer_layout(self, target: Target, thread_nums: int):
        raise NotImplementedError("infer_layout is not implemented")

    def lower(
        self,
        layout_map: dict,
        target: Target,
        thread_bounds: Range,
        thread_index: tirx.PrimExpr,
        mbar_phase_expr: tirx.PrimExpr | None = None,
    ):
        raise NotImplementedError("lower is not implemented")

    def is_gemm_ss(self) -> bool:
        """Return True if both A and B are in shared memory (SS variant)."""
        return is_shared(self.A) and is_shared(self.B)

    def is_gemm_sr(self) -> bool:
        """Return True if A is in shared memory and B is in registers (SR variant)."""
        return is_shared(self.A) and is_fragment(self.B)

    def is_gemm_rs(self) -> bool:
        """Return True if A is in registers and B is in shared memory (RS variant)."""
        return is_fragment(self.A) and is_shared(self.B)

    def is_gemm_ts(self) -> bool:
        """Return True if A is in tensor memory and B is in shared memory (TS variant)."""
        return is_tensor_memory(self.A) and is_shared(self.B)

    def is_gemm_rr(self) -> bool:
        """Return True if both A and B are in registers (RR variant)."""
        return is_fragment(self.A) and is_fragment(self.B)

    @property
    def M(self) -> int:
        return getattr(self.gemm_node, "m", None)

    @property
    def N(self) -> int:
        return getattr(self.gemm_node, "n", None)

    @property
    def K(self) -> int:
        return getattr(self.gemm_node, "k", None)

    @property
    def trans_A(self) -> bool:
        return getattr(self.gemm_node, "transA", None)

    @property
    def trans_B(self) -> bool:
        return getattr(self.gemm_node, "transB", None)

    @property
    def a_dtype(self):
        """A operand dtype."""
        return self.A.dtype

    @property
    def b_dtype(self):
        """B operand dtype."""
        return self.B.dtype

    @property
    def accum_dtype(self) -> str:
        return self.C.dtype

    @property
    def chunk(self) -> int:
        return self.K

    @property
    def A(self) -> tirx.Buffer:
        return getattr(self.gemm_node, "a", None)

    @property
    def B(self) -> tirx.Buffer:
        return getattr(self.gemm_node, "b", None)

    @property
    def C(self) -> tirx.Buffer:
        return getattr(self.gemm_node, "c", None)

    @property
    def ARegion(self):
        return getattr(self.gemm_node, "aRegion", None)

    @property
    def BRegion(self):
        return getattr(self.gemm_node, "bRegion", None)

    @property
    def CRegion(self):
        return getattr(self.gemm_node, "cRegion", None)

    @property
    def stride_A(self) -> int:
        return getattr(self.gemm_node, "strideA", None)

    @property
    def stride_B(self) -> int:
        return getattr(self.gemm_node, "strideB", None)

    @property
    def offset_A(self) -> int:
        return getattr(self.gemm_node, "offsetA", None)

    @property
    def offset_B(self) -> int:
        return getattr(self.gemm_node, "offsetB", None)

    @property
    def clear_accum(self) -> PrimExpr:
        return getattr(self.gemm_node, "clearAccum", None)

    @property
    def k_pack(self) -> int:
        return getattr(self.gemm_node, "kPack", None)

    @property
    def wg_wait(self) -> int:
        return getattr(self.gemm_node, "wgWait", 0)

    @property
    def is_tcgen05(self) -> bool:
        return getattr(self.gemm_node, "isTcgen05", False)

    @property
    def policy(self) -> GemmWarpPolicy:
        return getattr(self.gemm_node, "policy", None)

    @property
    def mbarptr(self) -> PrimExpr:
        return getattr(self.gemm_node, "mbarPtr", tvm.tirx.const(0, T.uint32))

    @property
    def mbar(self) -> tirx.BufferLoad | None:
        return getattr(self.gemm_node, "mbar", None)

    @property
    def C_coords(self):
        coords = getattr(self.gemm_node, "cCoords", None)
        if coords is None or len(coords) == 0:
            zero = tvm.tirx.const(0, T.int32)
            return [zero, zero]
        return [coords[i] for i in range(len(coords))]

    @property
    def SFARegion(self):
        return getattr(self.gemm_node, "sfaRegion", None)

    @property
    def SFBRegion(self):
        return getattr(self.gemm_node, "sfbRegion", None)

    @property
    def sf_k_start(self) -> PrimExpr:
        return getattr(self.gemm_node, "sfKStart", tvm.tirx.const(0, T.int32))

    @property
    def is_blockscaled(self) -> bool:
        return self.SFARegion is not None and self.SFBRegion is not None

    def get_region_base_offsets(self, region):
        """
        Get the base offset (start index) for each dimension from a BufferRegion.

        For example, if region is A_shared[ko % 2, 0:128, 0:64],
        this returns [ko % 2, 0, 0]

        Args:
            region: BufferRegion object

        Returns:
            List of PrimExpr representing the base offset for each dimension
        """
        if region is None:
            return []
        return [r.min for r in region.region]

    @property
    def A_base_offsets(self):
        """Get base offsets for each dimension of A region"""
        return self.get_region_base_offsets(self.ARegion)

    @property
    def B_base_offsets(self):
        """Get base offsets for each dimension of B region"""
        return self.get_region_base_offsets(self.BRegion)

    @property
    def C_base_offsets(self):
        """Get base offsets for each dimension of C region"""
        return self.get_region_base_offsets(self.CRegion)

